INSERT INTO diseases (label, tanaman, penyakit, status, deskripsi, gejala, perawatan, rekomendasi_obat, tingkat_keparahan, terdeteksi_ai) VALUES
("Apple___Apple_scab", "Apel", "Kudis Apel (Apple Scab)", "sakit", "Penyakit jamur yang disebabkan oleh Venturia inaequalis, menyerang daun dan buah apel terutama saat musim lembap.", "Bercak hijau zaitun hingga hitam berbentuk tidak beraturan pada daun, daun menguning dan rontok lebih awal, permukaan buah retak dan berkerak.", "Pangkas dan buang daun/ranting terinfeksi, jaga sirkulasi udara antar tanaman, hindari penyiraman ke daun, kumpulkan dan musnahkan daun gugur di musim gugur.", "Fungisida berbahan aktif Captan atau Mankozeb, disemprotkan sejak tunas mulai muncul dengan interval 7-10 hari.", "sedang", TRUE),
("Apple___Black_rot", "Apel", "Busuk Hitam (Black Rot)", "sakit", "Disebabkan jamur Botryosphaeria obtusa, menyerang daun, batang, dan buah apel.", "Bercak coklat keunguan pada daun dengan pola cincin konsentris, buah membusuk dan menghitam mulai dari titik luka.", "Pangkas cabang mati atau kanker pada batang, buang buah yang membusuk agar tidak jadi sumber infeksi, sanitasi kebun secara rutin.", "Fungisida berbahan aktif Thiophanate-methyl atau Captan sesuai dosis anjuran pada label.", "sedang-tinggi", TRUE),
("Apple___Cedar_apple_rust", "Apel", "Karat Apel-Cedar (Cedar Apple Rust)", "sakit", "Penyakit jamur yang membutuhkan dua inang: pohon apel dan pohon cedar/juniper di sekitarnya.", "Bercak oranye cerah menyerupai karat pada permukaan daun, bintik-bintik kecil yang membesar seiring waktu.", "Jauhkan pohon apel dari pohon cedar/juniper (jarak minimal beberapa ratus meter jika memungkinkan), buang daun terinfeksi.", "Fungisida berbahan aktif Myclobutanil disemprotkan mulai fase tunas merah muda.", "ringan-sedang", TRUE),
("Apple___healthy", "Apel", "Sehat", "sehat", "Daun apel dalam kondisi sehat, tidak menunjukkan tanda infeksi jamur atau bakteri.", "Warna daun hijau merata, tidak ada bercak, tidak ada layu atau perubahan tekstur.", "Lanjutkan penyiraman teratur, pemupukan berimbang, dan pemangkasan rutin untuk menjaga sirkulasi udara.", "Tidak diperlukan pestisida. Cukup pupuk seimbang NPK sesuai fase pertumbuhan.", "tidak ada", TRUE),
("Blueberry___healthy", "Blueberry", "Sehat", "sehat", "Tanaman blueberry dalam kondisi sehat tanpa tanda penyakit.", "Daun hijau segar, pertumbuhan normal.", "Jaga pH tanah asam (4.5-5.5), penyiraman cukup, dan mulsa untuk menjaga kelembapan tanah.", "Tidak diperlukan pestisida. Gunakan pupuk khusus tanaman berry.", "tidak ada", TRUE),
("Cherry_(including_sour)___Powdery_mildew", "Ceri", "Embun Tepung (Powdery Mildew)", "sakit", "Infeksi jamur yang membentuk lapisan putih seperti tepung pada permukaan daun.", "Lapisan putih bertepung pada daun dan pucuk muda, daun keriting dan pertumbuhan terhambat.", "Tingkatkan sirkulasi udara dengan pemangkasan, hindari pemupukan nitrogen berlebih, buang bagian tanaman yang terinfeksi berat.", "Fungisida berbahan aktif sulfur atau Myclobutanil, atau larutan baking soda untuk infeksi ringan.", "ringan-sedang", TRUE),
("Cherry_(including_sour)___healthy", "Ceri", "Sehat", "sehat", "Tanaman ceri dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata tanpa bercak atau lapisan putih.", "Lanjutkan perawatan rutin: penyiraman, pemupukan, dan pemangkasan bentuk.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Corn_(maize)___Cercospora_leaf_spot Gray_leaf_spot", "Jagung", "Bercak Daun Cercospora / Gray Leaf Spot", "sakit", "Penyakit jamur yang berkembang pesat pada kondisi lembap dan padat tanam tinggi.", "Bercak persegi panjang berwarna coklat keabuan sejajar tulang daun, dapat menyatu dan mengeringkan seluruh daun.", "Rotasi tanaman dengan non-serealia, kurangi kepadatan tanam, bersihkan sisa tanaman setelah panen.", "Fungisida berbahan aktif Azoxystrobin atau Propiconazole bila serangan berat.", "sedang-tinggi", TRUE),
("Corn_(maize)___Common_rust_", "Jagung", "Karat Daun Jagung (Common Rust)", "sakit", "Disebabkan jamur Puccinia sorghi, umum muncul pada musim dengan kelembapan tinggi.", "Bintil-bintil kecil coklat kemerahan (pustul) tersebar di kedua sisi permukaan daun.", "Gunakan varietas tahan karat, hindari kelembapan berlebih di sekitar tanaman, jaga jarak tanam.", "Fungisida berbahan aktif Mankozeb atau Propiconazole jika serangan meluas.", "ringan-sedang", TRUE),
("Corn_(maize)___Northern_Leaf_Blight", "Jagung", "Hawar Daun Utara (Northern Leaf Blight)", "sakit", "Penyakit jamur yang menyebabkan lesi panjang berbentuk cerutu pada daun jagung.", "Lesi abu-abu kehijauan memanjang seperti cerutu, dapat menyatu dan mengeringkan seluruh daun.", "Rotasi tanaman, tanam varietas tahan, olah sisa tanaman setelah panen untuk mengurangi sumber infeksi.", "Fungisida berbahan aktif Azoxystrobin + Propiconazole pada fase awal serangan.", "sedang-tinggi", TRUE),
("Corn_(maize)___healthy", "Jagung", "Sehat", "sehat", "Tanaman jagung dalam kondisi sehat tanpa gejala penyakit daun.", "Daun hijau merata, tegak, tanpa bercak.", "Lanjutkan pemupukan berimbang dan pengairan sesuai fase pertumbuhan.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Grape___Black_rot", "Anggur", "Busuk Hitam (Black Rot)", "sakit", "Salah satu penyakit paling merusak pada tanaman anggur, disebabkan jamur Guignardia bidwellii.", "Bercak coklat bulat pada daun dengan titik hitam kecil, buah mengeriput menjadi hitam keras seperti kismis.", "Pangkas dan musnahkan bagian terinfeksi, buang buah yang mumifikasi, jaga sirkulasi udara di kanopi.", "Fungisida berbahan aktif Mankozeb atau Myclobutanil mulai dari fase tunas hingga buah terbentuk.", "tinggi", TRUE),
("Grape___Esca_(Black_Measles)", "Anggur", "Esca (Black Measles)", "sakit", "Penyakit kompleks akibat beberapa jenis jamur yang menyerang jaringan kayu tanaman anggur tua.", "Garis-garis kuning/merah di antara tulang daun (seperti macan tutul), buah berbintik gelap, daun kering mendadak.", "Pangkas dan bakar kayu yang terinfeksi, hindari luka pemangkasan besar saat musim hujan, tutup luka pangkas dengan pasta pelindung.", "Belum ada fungisida yang sepenuhnya efektif; fokus pada pencegahan dan sanitasi kebun.", "tinggi", TRUE),
("Grape___Leaf_blight_(Isariopsis_Leaf_Spot)", "Anggur", "Hawar Daun (Isariopsis Leaf Spot)", "sakit", "Infeksi jamur yang menyerang daun anggur dan menyebabkan gugur daun dini.", "Bercak coklat kemerahan dengan tepi tidak beraturan, daun menguning lalu gugur.", "Buang daun terinfeksi, perbaiki drainase kebun, jaga jarak tanam agar sirkulasi udara baik.", "Fungisida berbahan aktif tembaga (Copper oxychloride) atau Mankozeb.", "sedang", TRUE),
("Grape___healthy", "Anggur", "Sehat", "sehat", "Tanaman anggur dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau segar tanpa bercak maupun garis warna abnormal.", "Lanjutkan pemangkasan rutin dan pemupukan sesuai fase pertumbuhan.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Orange___Haunglongbing_(Citrus_greening)", "Jeruk", "Citrus Greening (Huanglongbing/CVPD)", "sakit", "Penyakit bakteri yang disebarkan oleh serangga kutu loncat jeruk (Diaphorina citri), sangat merusak dan belum ada obatnya.", "Daun belang kuning tidak simetris (blotchy mottle), buah kecil, asimetris, dan terasa pahit, ranting mati dari pucuk.", "Cabut dan musnahkan tanaman yang terinfeksi berat untuk mencegah penyebaran, kendalikan populasi kutu loncat jeruk sebagai vektor.", "Insektisida untuk mengendalikan vektor (kutu loncat) seperti Imidakloprid; tidak ada obat langsung untuk bakterinya.", "sangat tinggi", TRUE),
("Peach___Bacterial_spot", "Persik", "Bercak Bakteri (Bacterial Spot)", "sakit", "Infeksi bakteri Xanthomonas yang menyerang daun, ranting, dan buah persik.", "Bercak kecil kehitaman dengan halo kuning pada daun, daun berlubang seperti tembakan peluru, buah bercak cekung.", "Hindari penyiraman ke daun, pangkas untuk sirkulasi udara, buang bagian terinfeksi.", "Bakterisida berbahan aktif tembaga (Copper) disemprotkan saat dorman dan awal musim semi.", "sedang", TRUE),
("Peach___healthy", "Persik", "Sehat", "sehat", "Tanaman persik dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata tanpa bercak atau lubang.", "Lanjutkan penyiraman dan pemupukan rutin sesuai fase pertumbuhan.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Pepper,_bell___Bacterial_spot", "Paprika/Cabai Bell", "Bercak Bakteri (Bacterial Spot)", "sakit", "Infeksi bakteri Xanthomonas campestris yang menyerang daun dan buah paprika.", "Bercak kecil basah berair yang menjadi coklat kehitaman dengan tepi kuning, daun rontok bila serangan berat.", "Gunakan benih/bibit bebas penyakit, hindari penyiraman ke daun, rotasi tanaman, jaga jarak tanam.", "Bakterisida berbahan aktif tembaga (Copper hydroxide) dikombinasikan dengan Mankozeb.", "sedang", TRUE),
("Pepper,_bell___healthy", "Paprika/Cabai Bell", "Sehat", "sehat", "Tanaman paprika dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata, tidak ada bercak air atau layu.", "Lanjutkan penyiraman teratur dan pemupukan berimbang.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Potato___Early_blight", "Kentang", "Hawar Dini (Early Blight)", "sakit", "Disebabkan jamur Alternaria solani, sering menyerang tanaman yang sudah stres atau kekurangan nutrisi.", "Bercak coklat gelap dengan pola cincin konsentris menyerupai sasaran (target board) pada daun tua terlebih dahulu.", "Rotasi tanaman, buang daun terinfeksi, jaga kesuburan tanah dan pemupukan berimbang agar tanaman tidak stres.", "Fungisida berbahan aktif Klorotalonil atau Mankozeb dengan interval 7-10 hari.", "sedang", TRUE),
("Potato___Late_blight", "Kentang", "Hawar Daun / Busuk Daun (Late Blight)", "sakit", "Penyakit sangat merusak disebabkan Phytophthora infestans, penyebab utama Kelaparan Besar Irlandia; menyebar cepat pada cuaca lembap dan sejuk.", "Bercak basah berwarna coklat gelap kehijauan dengan tepi tidak jelas, muncul lapisan putih di bawah daun saat lembap, umbi membusuk.", "Segera buang dan musnahkan tanaman terinfeksi, hindari penyiraman ke daun di sore/malam hari, tingkatkan jarak tanam untuk sirkulasi udara.", "Fungisida berbahan aktif Klorotalonil, Mankozeb, atau Metalaxyl untuk infeksi sistemik; semprot preventif saat cuaca lembap.", "sangat tinggi", TRUE),
("Potato___healthy", "Kentang", "Sehat", "sehat", "Tanaman kentang dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata tanpa bercak coklat atau lapisan jamur.", "Lanjutkan penyiraman dan pemupukan rutin, jaga drainase lahan.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Raspberry___healthy", "Rasberi", "Sehat", "sehat", "Tanaman rasberi dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau segar, pertumbuhan normal.", "Lanjutkan pemangkasan dan pemupukan rutin.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Soybean___healthy", "Kedelai", "Sehat", "sehat", "Tanaman kedelai dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata, tidak ada bercak atau layu.", "Lanjutkan pemupukan dan pengairan sesuai fase pertumbuhan.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Squash___Powdery_mildew", "Labu", "Embun Tepung (Powdery Mildew)", "sakit", "Infeksi jamur umum pada tanaman labu-labuan terutama saat kelembapan tinggi dan sirkulasi udara buruk.", "Lapisan putih seperti tepung menutupi permukaan daun dan batang, daun menguning dan mengering.", "Tingkatkan jarak tanam untuk sirkulasi udara, buang daun terinfeksi berat, hindari pemupukan nitrogen berlebihan.", "Fungisida berbahan aktif sulfur atau Potassium bicarbonate untuk kasus ringan-sedang.", "sedang", TRUE),
("Strawberry___Leaf_scorch", "Stroberi", "Hangus Daun (Leaf Scorch)", "sakit", "Disebabkan jamur Diplocarpon earlianum, umum pada kondisi lembap berkepanjangan.", "Bercak ungu kecil yang menyatu menjadi area besar berwarna coklat kemerahan menyerupai daun terbakar.", "Buang daun tua/terinfeksi setelah panen, jaga jarak tanam, hindari penyiraman ke daun.", "Fungisida berbahan aktif Klorotalonil atau Captan pada awal musim tanam.", "sedang", TRUE),
("Strawberry___healthy", "Stroberi", "Sehat", "sehat", "Tanaman stroberi dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau segar tanpa bercak ungu/coklat.", "Lanjutkan penyiraman teratur dan pemberian mulsa.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("Tomato___Bacterial_spot", "Tomat", "Bercak Bakteri (Bacterial Spot)", "sakit", "Infeksi bakteri Xanthomonas yang menyebar cepat pada kondisi hangat dan lembap, sering melalui percikan air hujan.", "Bercak kecil kehitaman berair pada daun dan buah, daun menguning dan rontok bila parah.", "Gunakan bibit sehat bersertifikat, hindari penyiraman ke daun, rotasi tanaman dengan famili berbeda minimal 2 tahun.", "Bakterisida berbahan aktif tembaga (Copper hydroxide) dikombinasi Mankozeb.", "sedang", TRUE),
("Tomato___Early_blight", "Tomat", "Hawar Dini (Early Blight)", "sakit", "Disebabkan jamur Alternaria solani, umumnya menyerang daun tua terlebih dahulu lalu menyebar ke atas.", "Bercak coklat dengan cincin konsentris menyerupai sasaran tembak, daun menguning di sekitar bercak lalu rontok.", "Pangkas daun bagian bawah yang terinfeksi, beri jarak tanam cukup, gunakan mulsa untuk mencegah percikan tanah ke daun.", "Fungisida berbahan aktif Klorotalonil atau Mankozeb setiap 7-10 hari saat gejala muncul.", "sedang", TRUE),
("Tomato___Late_blight", "Tomat", "Hawar Daun / Busuk Daun (Late Blight)", "sakit", "Penyakit sangat merusak disebabkan Phytophthora infestans, dapat menghancurkan tanaman dalam hitungan hari saat cuaca lembap dan sejuk.", "Bercak besar coklat kehijauan basah dengan tepi kuning pucat, muncul jamur putih di bawah daun saat lembap, buah membusuk cepat.", "Segera cabut dan musnahkan tanaman terinfeksi berat, jangan disiram dari atas, tingkatkan sirkulasi udara antar tanaman.", "Fungisida berbahan aktif Klorotalonil, Mankozeb, atau Metalaxyl-M; semprot preventif sebelum musim hujan.", "sangat tinggi", TRUE),
("Tomato___Leaf_Mold", "Tomat", "Kapang Daun (Leaf Mold)", "sakit", "Disebabkan jamur Passalora fulva, umum di rumah kaca atau area dengan kelembapan tinggi dan sirkulasi udara buruk.", "Bercak kuning pucat di permukaan atas daun, lapisan beludru abu-kehijauan hingga coklat di bagian bawah daun.", "Tingkatkan ventilasi/sirkulasi udara, kurangi kelembapan, buang daun terinfeksi.", "Fungisida berbahan aktif Klorotalonil atau Mankozeb.", "sedang", TRUE),
("Tomato___Septoria_leaf_spot", "Tomat", "Bercak Daun Septoria (Septoria Leaf Spot)", "sakit", "Disebabkan jamur Septoria lycopersici, menyerang daun bagian bawah terlebih dahulu.", "Bercak kecil bulat dengan pusat abu-abu dan tepi gelap, titik-titik hitam kecil (piknidia) di tengah bercak.", "Buang daun bawah yang terinfeksi, hindari penyiraman ke daun, beri mulsa untuk mencegah percikan tanah.", "Fungisida berbahan aktif Klorotalonil atau tembaga (Copper) setiap 7-10 hari.", "sedang", TRUE),
("Tomato___Spider_mites Two-spotted_spider_mite", "Tomat", "Tungau Laba-laba (Two-Spotted Spider Mite)", "sakit", "Hama tungau mikroskopis yang menyerang saat cuaca panas dan kering, bukan jamur/bakteri melainkan hama.", "Bintik-bintik kuning kecil (stippling) pada daun, jaring halus di bawah daun pada serangan berat, daun menguning dan kering.", "Semprot air bertekanan untuk merontokkan tungau, jaga kelembapan lingkungan, gunakan predator alami seperti tungau predator.", "Akarisida/miticide berbahan aktif Abamektin, atau sabun insektisida (insecticidal soap) untuk kasus ringan.", "sedang", TRUE),
("Tomato___Target_Spot", "Tomat", "Bercak Target (Target Spot)", "sakit", "Disebabkan jamur Corynespora cassiicola, menyerang daun, batang, dan buah tomat.", "Bercak coklat dengan cincin konsentris mirip early blight namun lebih kecil dan bisa muncul di batang serta buah.", "Rotasi tanaman, jaga jarak tanam, buang bagian tanaman terinfeksi, kurangi kelembapan daun.", "Fungisida berbahan aktif Klorotalonil atau Azoxystrobin.", "sedang", TRUE),
("Tomato___Tomato_Yellow_Leaf_Curl_Virus", "Tomat", "Virus Kuning Keriting Daun (Tomato Yellow Leaf Curl Virus)", "sakit", "Penyakit virus yang ditularkan oleh kutu kebul (whitefly), sangat merugikan produksi tomat.", "Daun menguning dan menggulung ke atas, tanaman kerdil, bunga rontok sehingga buah gagal terbentuk.", "Cabut dan musnahkan tanaman terinfeksi, kendalikan populasi kutu kebul sebagai vektor, gunakan mulsa plastik perak untuk mengusir kutu kebul.", "Insektisida untuk mengendalikan kutu kebul seperti Imidakloprid; tidak ada obat langsung untuk virusnya.", "tinggi", TRUE),
("Tomato___Tomato_mosaic_virus", "Tomat", "Virus Mosaik Tomat (Tomato Mosaic Virus)", "sakit", "Penyakit virus yang menular lewat kontak fisik/alat pertanian yang terkontaminasi, sangat stabil dan tahan lama di lingkungan.", "Pola belang hijau muda-tua (mosaik) pada daun, daun menggulung dan tanaman tumbuh kerdil.", "Cabut dan musnahkan tanaman terinfeksi, sterilkan alat pertanian, cuci tangan sebelum menyentuh tanaman sehat, hindari merokok di dekat tanaman (virus terkait tembakau).", "Tidak ada obat kimia untuk virus; fokus pada pencegahan penularan dan sanitasi.", "tinggi", TRUE),
("Tomato___healthy", "Tomat", "Sehat", "sehat", "Tanaman tomat dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata, tidak ada bercak, tidak menggulung atau menguning.", "Lanjutkan penyiraman teratur, pemupukan berimbang, dan pemasangan ajir agar sirkulasi udara baik.", "Tidak diperlukan pestisida.", "tidak ada", TRUE),
("manual___Padi_Blas_Blast", "Padi", "Blas (Blast)", "sakit", "Disebabkan jamur Magnaporthe oryzae, salah satu penyakit paling merusak pada padi di Indonesia, menyerang daun hingga malai.", "Bercak berbentuk belah ketupat dengan pusat abu-abu dan tepi coklat pada daun, pada malai menyebabkan patah leher (neck blast) sehingga gabah hampa.", "Gunakan varietas tahan blas, atur jarak tanam agar tidak terlalu rapat, hindari pemupukan nitrogen berlebihan, jaga drainase sawah.", "Fungisida berbahan aktif Trisiklazol atau Isoprotiolan sesuai dosis anjuran.", "tinggi", FALSE),
("manual___Padi_Hawar_Daun_Bakteri", "Padi", "Hawar Daun Bakteri (Bacterial Leaf Blight/Kresek)", "sakit", "Disebabkan bakteri Xanthomonas oryzae, dikenal petani sebagai penyakit kresek, dapat menyebabkan gagal panen besar.", "Daun menguning dari ujung/tepi lalu mengering seperti terbakar, pada serangan berat seluruh tanaman muda bisa layu dan mati (kresek).", "Gunakan benih sehat dan varietas tahan, hindari pemupukan nitrogen berlebihan, perbaiki drainase, jangan biarkan sawah tergenang berlebihan.", "Bakterisida berbahan aktif tembaga (Copper) atau Streptomycin sulfate sesuai anjuran PPL setempat.", "tinggi", FALSE),
("manual___Padi_Tungro", "Padi", "Tungro", "sakit", "Penyakit virus yang ditularkan wereng hijau, salah satu penyakit endemik penting pada tanaman padi di Indonesia.", "Tanaman kerdil, daun menguning hingga jingga dimulai dari ujung daun, jumlah anakan berkurang, hasil gabah menurun drastis.", "Tanam serentak dan gunakan varietas tahan tungro, kendalikan populasi wereng hijau sebagai vektor, cabut tanaman terinfeksi berat.", "Insektisida untuk mengendalikan wereng hijau seperti Imidakloprid; tidak ada obat langsung untuk virusnya.", "tinggi", FALSE),
("manual___Cabai_Antraknosa", "Cabai", "Antraknosa / Patek", "sakit", "Disebabkan jamur Colletotrichum sp., penyakit paling ditakuti petani cabai karena menyerang buah menjelang panen.", "Bercak cekung coklat kehitaman melingkar pada buah dengan titik-titik spora di tengahnya, buah membusuk dan rontok.", "Petik dan musnahkan buah terinfeksi, jaga jarak tanam untuk sirkulasi udara, rotasi tanaman, hindari kelembapan berlebih.", "Fungisida berbahan aktif Mankozeb, Klorotalonil, atau Difenokonazol, semprot preventif sebelum musim hujan.", "sangat tinggi", FALSE),
("manual___Cabai_Layu_Fusarium", "Cabai", "Layu Fusarium", "sakit", "Infeksi jamur tular tanah Fusarium oxysporum yang menyerang jaringan pembuluh akar dan batang.", "Daun layu dimulai dari bawah, menguning, batang bagian dalam menghitam jika dibelah, tanaman mati perlahan meski tanah cukup air.", "Rotasi tanaman dengan non-solanaceae, perbaiki drainase lahan, cabut dan musnahkan tanaman terinfeksi, sterilkan alat pertanian.", "Fungisida sistemik berbahan aktif Karbendazim melalui kocor akar; pencegahan lebih efektif daripada pengobatan.", "tinggi", FALSE),
("manual___Cabai_Virus_Kuning", "Cabai", "Virus Kuning (Gemini Virus)", "sakit", "Penyakit virus yang ditularkan kutu kebul (whitefly), sangat umum menyerang cabai terutama di musim kemarau.", "Daun menguning cerah dengan tulang daun tetap hijau (mosaik kuning), daun menggulung ke atas dan tanaman kerdil.", "Kendalikan populasi kutu kebul, gunakan mulsa plastik perak, cabut tanaman terinfeksi berat, pasang perangkap kuning lengket.", "Insektisida untuk kutu kebul seperti Imidakloprid atau Tiametoksam; tidak ada obat langsung untuk virusnya.", "tinggi", FALSE),
("manual___Terong_Layu_Bakteri", "Terong", "Layu Bakteri", "sakit", "Disebabkan bakteri Ralstonia solanacearum, menyerang sistem pembuluh tanaman dan menyebar cepat lewat tanah dan air.", "Tanaman layu mendadak meski tanah lembap, biasanya dimulai dari daun muda, jika batang dipotong keluar lendir putih susu.", "Rotasi tanaman dengan famili berbeda, perbaiki drainase, cabut dan musnahkan tanaman terinfeksi, sterilkan alat pertanian.", "Belum ada bakterisida yang benar-benar efektif; fokus pada pencegahan dan sanitasi lahan.", "tinggi", FALSE),
("manual___Timun_Downy_Mildew", "Timun", "Downy Mildew (Bulai)", "sakit", "Penyakit jamur yang menyerang tanaman famili labu-labuan termasuk timun, berkembang pesat pada kondisi lembap.", "Bercak kuning bersudut dibatasi tulang daun pada permukaan atas, lapisan jamur keabuan di bawah daun saat pagi hari.", "Tingkatkan jarak tanam untuk sirkulasi udara, hindari penyiraman ke daun sore hari, buang daun terinfeksi.", "Fungisida berbahan aktif Mankozeb atau tembaga (Copper) disemprotkan preventif.", "sedang", FALSE),
("manual___Kubis_Akar_Gada", "Kubis", "Akar Gada (Clubroot)", "sakit", "Disebabkan organisme mirip jamur Plasmodiophora brassicae yang menyerang akar tanaman kubis-kubisan.", "Akar membengkak tidak beraturan menyerupai gada/tongkat, tanaman layu di siang hari terutama saat panas, pertumbuhan kerdil.", "Rotasi tanaman minimal 4-7 tahun, naikkan pH tanah dengan pengapuran (organisme ini menyukai tanah asam), perbaiki drainase.", "Fungisida tanah berbahan aktif Flusulfamide; pencegahan lewat pengapuran tanah lebih efektif jangka panjang.", "tinggi", FALSE),
("manual___BawangMerah_Antraknosa", "Bawang Merah", "Antraknosa / Trotol / Otomotis", "sakit", "Disebabkan jamur Colletotrichum gloeosporioides, menyebabkan daun bawang merah terpuntir dan mengering.", "Bercak putih hingga kekuningan berbentuk oval pada daun, daun terpuntir dan mengering, umbi menjadi kecil dan busuk.", "Gunakan bibit sehat, rotasi tanaman, jaga drainase agar tidak tergenang, hindari penyiraman berlebih.", "Fungisida berbahan aktif Mankozeb atau Difenokonazol dengan interval 5-7 hari saat cuaca lembap.", "tinggi", FALSE),
("manual___KacangPanjang_KaratDaun", "Kacang Panjang", "Karat Daun", "sakit", "Disebabkan jamur Uromyces spp., umum menyerang tanaman kacang-kacangan terutama di musim hujan.", "Bintil-bintil kecil coklat kemerahan (pustul) pada permukaan bawah daun, daun menguning dan rontok pada serangan berat.", "Jaga jarak tanam untuk sirkulasi udara, buang daun terinfeksi, rotasi tanaman dengan famili berbeda.", "Fungisida berbahan aktif Mankozeb atau sulfur.", "sedang", FALSE),
("manual___Singkong_BercakDaun", "Singkong", "Bercak Daun Cercospora", "sakit", "Disebabkan jamur Cercospora spp., penyakit umum pada daun singkong terutama di lahan dengan kelembapan tinggi.", "Bercak coklat kecil dengan tepi kekuningan tersebar di permukaan daun, daun menguning dan gugur pada serangan berat.", "Jaga jarak tanam, buang daun bawah yang terinfeksi berat, hindari penanaman terlalu rapat.", "Fungisida berbahan aktif Mankozeb bila serangan meluas; umumnya tidak terlalu mempengaruhi hasil umbi.", "ringan-sedang", FALSE),
("manual___KacangTanah_BercakDaun", "Kacang Tanah", "Bercak Daun (Leaf Spot)", "sakit", "Disebabkan jamur Cercospora arachidicola (bercak dini) atau Cercosporidium personatum (bercak lambat).", "Bercak coklat hingga kehitaman bulat dikelilingi halo kuning pada daun, daun rontok lebih awal bila serangan berat.", "Rotasi tanaman, jaga jarak tanam, bersihkan sisa tanaman setelah panen, gunakan varietas tahan bila tersedia.", "Fungisida berbahan aktif Klorotalonil atau Mankozeb dengan interval 10-14 hari.", "sedang", FALSE),
("manual___UbiJalar_KudisScab", "Ubi Jalar", "Kudis (Scab)", "sakit", "Disebabkan jamur Sphaceloma batatas, menyerang batang, tangkai daun, dan urat daun ubi jalar.", "Bercak kudis coklat kecoklatan bersisik pada batang dan urat daun, pertumbuhan tanaman terhambat dan kerdil.", "Gunakan bibit/stek sehat, rotasi tanaman, jaga jarak tanam untuk sirkulasi udara.", "Fungisida berbahan aktif tembaga (Copper) pada serangan awal.", "sedang", FALSE),
("manual___Padi_Sehat", "Padi", "Sehat", "sehat", "Tanaman padi dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau segar, anakan tumbuh normal, tidak ada bercak atau layu.", "Lanjutkan pemupukan berimbang dan pengairan berselang (intermittent) sesuai fase pertumbuhan.", "Tidak diperlukan pestisida.", "tidak ada", FALSE),
("manual___Cabai_Sehat", "Cabai", "Sehat", "sehat", "Tanaman cabai dalam kondisi sehat tanpa gejala penyakit.", "Daun hijau merata, buah tumbuh normal tanpa bercak.", "Lanjutkan penyiraman teratur, pemupukan berimbang, dan pemasangan ajir bila perlu.", "Tidak diperlukan pestisida.", "tidak ada", FALSE);
