-- =========================================================
-- Plant Doctor - Database Schema & Seed Data
-- Import lewat phpMyAdmin (XAMPP) atau: mysql -u root -p < schema.sql
-- =========================================================

DROP TABLE IF EXISTS diseases;

CREATE TABLE diseases (
  id INT AUTO_INCREMENT PRIMARY KEY,
  label VARCHAR(150) NOT NULL UNIQUE,
  tanaman VARCHAR(100) NOT NULL,
  penyakit VARCHAR(150) NOT NULL,
  status ENUM("sehat","sakit") NOT NULL,
  deskripsi TEXT,
  gejala TEXT,
  perawatan TEXT,
  rekomendasi_obat TEXT,
  tingkat_keparahan VARCHAR(50),
  terdeteksi_ai BOOLEAN NOT NULL DEFAULT FALSE COMMENT "TRUE jika termasuk 38 kelas yang dikenali model AI, FALSE jika hanya bisa dicari manual",
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

